class _Cache_ref_shared_129138:
    """Simple LRU cache."""
    def __init__(self, maxsize=100):
        self._cache = ref_shared_129138
        self._order = []
        self._max = maxsize
    def get(self, key):
        if key in self._cache:
            self._order.remove(key)
